      nextWakeRelative: $("#next-wake-relative"),
      wakesToday: $("#wakes-today"),
      wakesRemaining: $("#wakes-remaining"),
      daysActive: $("#days-active"),
      wakesPerWeek: $("#wakes-per-week"),
